from __future__ import annotations

import json


def render_html(graph: dict) -> str:
    # Escaping '<' prevents a model-provided label from terminating the script tag.
    payload = json.dumps(graph, ensure_ascii=False).replace("<", "\\u003c")
    return _TEMPLATE.replace("__GRAPH_DATA__", payload)


